class Item:
    def __init__(self, name, path, is_dir_listing):
        self.name = name
        self.path = path
        self.is_dir_listing = is_dir_listing
        try:
            self.st = os.stat(path, follow_symlinks=False)
        except OSError:
            self.st = None

    @property
    def mode(self): return self.st.st_mode if self.st else 0

def sort_items(items, sort_bases):
    for base in reversed(sort_bases):
        rev = base.endswith('_')
        b = base.rstrip('_')

        def key_func(it):
            if b == 'name': return it.name
            if b == 'cname': return it.name.lower()
            if b == 'ext':
                parts = it.name.split('.')
                return parts[-1] if len(parts) > 1 else ""
            if b == 'size': return it.st.st_size if it.st else 0
            if b == 'mtime': return it.st.st_mtime if it.st else 0
            if b == 'ctime': return it.st.st_ctime if it.st else 0
            if b == 'atime': return it.st.st_atime if it.st else 0
            if b == 'btime': return getattr(it.st, 'st_birthtime', it.st.st_ctime if it.st else 0)
