                try: return pwd.getpwuid(it.st.st_uid).pw_name
                except: return str(it.st.st_uid) if it.st else ""
            if b == 'group':
                try: return grp.getgrgid(it.st.st_gid).gr_name
                except: return str(it.st.st_gid) if it.st else ""
            if b == 'inode': return it.st.st_ino if it.st else 0
            if b == 'blocks': return getattr(it.st, 'st_blocks', 0) if it.st else 0
            if b == 'nlinks': return it.st.st_nlink if it.st else 0
            return it.name.lower()

        items.sort(key=key_func, reverse=rev)

def get_row(item, args, cols):
    if not item.st: return {}
    row = {}
    st = item.st
    for c in cols:
        if c == 'Device': row[c] = str(st.st_dev)
        elif c == 'inode': row[c] = str(st.st_ino)
        elif c == 'Link#': row[c] = str(st.st_nlink)
