        elif c == 'Permissions': row[c] = mode_to_str(st.st_mode)
        elif c == 'SUGO': row[c] = f"{st.st_mode & 0o7777:4o}"
        elif c == 'User':
            try: row[c] = pwd.getpwuid(st.st_uid).pw_name
            except: row[c] = str(st.st_uid)
        elif c == 'UID': row[c] = str(st.st_uid)
        elif c == 'Group':
            try: row[c] = grp.getgrgid(st.st_gid).gr_name
            except: row[c] = str(st.st_gid)
        elif c == 'GID': row[c] = str(st.st_gid)
        elif c == 'Size':
            row[c] = format_size(st.st_size, args.unit) if not stat.S_ISDIR(st.st_mode) else ""
        elif c == 'Blocks': row[c] = str(getattr(st, 'st_blocks', 0))
        elif c == 'Created': row[c] = format_date(getattr(st, 'st_birthtime', st.st_ctime))
        elif c == 'Changed': row[c] = format_date(st.st_ctime)
        elif c == 'Modified': row[c] = format_date(st.st_mtime)
        elif c == 'Accessed': row[c] = format_date(st.st_atime)
        elif c == 'Git': row[c] = ""
    return row
