def apply_filters(items, args):
    res = []
    # typ
    types = set(args.typ)
    for it in items:
        if not it.st: continue
        t_str = get_type_str(it.st)
        m = False
        if 'all' in types: m = True
        if 'none' in types: m = False
        if 'dir' in types and t_str == 'd': m = True
        if 'symlink' in types and t_str == 'l': m = True
        if 'fifo' in types and t_str == 'p': m = True
        if 'socket' in types and t_str == 's': m = True
        if 'block-device' in types and t_str == 'b': m = True
        if 'char-device' in types and t_str == 'c': m = True
        if 'file' in types and t_str == 'f': m = True

        # importance
        if args.imp == '1' and it.name.startswith('.'): m = False
        if args.imp == '2': m = False

        # exclude/only
        if args.exclude:
            try:
                if re.search(args.exclude, it.name): m = False
            except: pass
        if args.only:
            try:
                if not re.search(args.only, it.name): m = False
            except: pass

        if m: res.append(it)
    return res

def render_items(items, args, is_dir_listing):
    if not items: return
    items = apply_filters(items, args)

    det = args.det
    cols = []
    for d in det:
        if d == 'std': cols.extend(['Link#', 'T', 'Permissions', 'User', 'Group', 'Size', 'Modified'])
        elif d == 'all': cols.extend(['Device', 'inode', 'Link#', 'T', 'Permissions', 'SUGO', 'User', 'UID', 'Group', 'GID', 'Size', 'Blocks', 'Created', 'Changed', 'Modified', 'Accessed', 'Git'])
        elif d == 'dev': cols.append('Device')
        elif d == 'ino': cols.append('inode')
        elif d == 'nlink': cols.append('Link#')
        elif d == 'typ': cols.append('T')
        elif d == 'perm': cols.append('Permissions')
        elif d == 'oct': cols.append('SUGO')
        elif d == 'user': cols.append('User')
        elif d == 'uid': cols.append('UID')
        elif d == 'group': cols.append('Group')
        elif d == 'gid': cols.append('GID')
        elif d == 'size': cols.append('Size')
        elif d == 'blocks': cols.append('Blocks')
        elif d == 'btime': cols.append('Created')
        elif d == 'ctime': cols.append('Changed')
        elif d == 'mtime': cols.append('Modified')
        elif d == 'atime': cols.append('Accessed')
        elif d == 'git': cols.append('Git')

    # Remove duplicates but preserve order
    seen = set()
    uniq_cols = []
    for c in cols:
        if c not in seen:
            uniq_cols.append(c)
            seen.add(c)

    cols = uniq_cols

    rows = []
    for it in items:
        r = get_row(it, args, cols)

        # construct name
        name = it.name
        is_dot = name.startswith('.')
        align = args.align == 'true' and is_dir_listing
        has_icon = False
        icon_str = ""

        if args.icon == 'true':
            ic = get_icon(it.name, it.st)
            if ic:
                has_icon = True
                icon_str = ic

        if args.icon == 'true':
            if has_icon:
                pad = "  " if not is_dot and align else " "
                prefix = icon_str + pad
            else:
                pad = "   " if not is_dot and align else "  "
                prefix = pad
        else:
            pad = " " if not is_dot and align else ""
            prefix = pad

        display_name = prefix + name

        if args.suffix == 'true':
            t = get_type_str(it.st)
            if t == 'd': display_name += "/"
            elif t == 'l': display_name += "@"
            elif t == 'p': display_name += "|"
            elif t == 's': display_name += "="

        if stat.S_ISLNK(it.st.st_mode):
            try:
                target = os.readlink(it.path)
                display_name += f" 󰁔 {target}"
            except: pass

        r['Name'] = display_name
        rows.append(r)

    if not rows: return

    all_cols = cols + ['Name']
    right_aligned = {'Device', 'inode', 'Link#', 'SUGO', 'UID', 'GID', 'Size', 'Blocks'}
    widths = {c: len(c) for c in all_cols}
    for r in rows:
        for c in all_cols:
            if c in r: widths[c] = max(widths[c], len(r[c]))

    if args.header == 'true' and cols:
        hdr = []
        for c in all_cols:
            if c in right_aligned: hdr.append(c.rjust(widths[c]))
            else: hdr.append(c.ljust(widths[c]))
        print(" ".join(hdr).rstrip())

    for r in rows:
        line = []
        for c in all_cols:
            v = r.get(c, "")
            if c in right_aligned: line.append(v.rjust(widths[c]))
            else: line.append(v.ljust(widths[c]))
        print(" ".join(line).rstrip())
