        elif c == 'Blocks': row[c] = str(getattr(st, 'st_blocks', 0))
        elif c == 'Created': row[c] = format_date(getattr(st, 'st_birthtime', st.st_ctime))
        elif c == 'Changed': row[c] = format_date(st.st_ctime)
        elif c == 'Modified': row[c] = format_date(st.st_mtime)
        elif c == 'Accessed': row[c] = format_date(st.st_atime)
        elif c == 'Git': row[c] = ""
