def apply_filters(items, args):
    res = []
    types = set(args.typ)
    for it in items:
        if not it.st: continue
        t_str = get_type_str(it.st)
        m = False
        if 'all' in types: m = True
        if 'none' in types: m = False
        if 'dir' in types and t_str == 'd': m = True
        if 'symlink' in types and t_str == 'l': m = True
        if 'fifo' in types and t_str == 'p': m = True
        if 'socket' in types and t_str == 's': m = True
        if 'block-device' in types and t_str == 'b': m = True
        if 'char-device' in types and t_str == 'c': m = True
        if 'file' in types and t_str == 'f': m = True

        if args.imp == '1' and os.path.basename(it.name).startswith('.'): m = False
        if args.imp == '2': m = False

        if args.exclude:
            try:
                if re.search(args.exclude, it.name): m = False
            except: pass
        if args.only:
            try:
                if not re.search(args.only, it.name): m = False
            except: pass

        if m: res.append(it)
    return res

